function demoMain(idx,label){
  var commits=[["a1","init"],["b2","add parser"],["c3","fix lexer"],["d4","add tests"]];
  var n=2+(idx%3); var log=commits.slice(0,n).map(function(c){return c[0]+" "+c[1];});
  var diff="+"+n+" files changed, "+(n*14)+" insertions(+)";
  return "["+label+"] log ("+n+" commits): "+log.join(" | ")+" || diff HEAD~1: "+diff;
}

